SELECT 'bf-ats-greens-paradiso-terms', 'bf-ats-greens-paradiso-contract', 1, '2026-06-01'::date, 'negotiated_fixed',
       5, 60, 6.30,
       '[{"circuitId": "bf-ats-greens-paradiso-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 40, "representedLightCount": 951, "benchmarkSavingsPct": 64.43, "preInstallBaseline": 18.71, "projectedSavedKwhPerDay": 12.0549}]'::jsonb, a.id, now()
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
